-- Touches: sales.list_sales_orders, sales.search_sales_orders
-- Safety: security definer, tenant scoped, read-only exists on einvoice.electronic_invoices
-- Depends on: 20260830010_sales_inquiry_receipt_rpcs.sql, 007_einvoice_issuance_schema_and_publish_rpcs.sql
